el Adapter, particularly for its broad plug compatibility. \ue200cite\ue202turn525619search5\ue201\n\n**My pick\\:** The UGREEN 100W charger and 20,000m"},{"p":"/message/metadata/model_dil_v2/appData/opGenui/componentResults/942d2c4a-6ecd-545a-a687-b8420b25b9e3","o":"add","v":{"status":"resolved","state":{"items":[{"url":"https://www.wired.com/gallery/best-travel-adapters/?utm_source=chatgpt.com","ref_id":"turn525619search5","refs":[{"turn_index":525619,"ref_type":"search","ref_index":5}],"source_label":"WIRED","source_name":"WIRED","title":"8 Best Travel Adapters (2026): 20+ Models Tested","snippet":null,"pub_timestamp":1789084800.0,"metadata_label":"September 11, 2026"}],"active_index":0,"sources_title":"1 Source"},"safe_urls":["https://www.wired.com/gallery/best-travel-adapters/?utm_source=chatgpt.com"],"hide_widget_feedback":true,"componentName":"Cite"}},{"p":"/message/metadata/genui_components","o":"append","v":[{"type":"cite","tree_range":[78,79],"start_index":3409,"end_index":3440,"component_resolution_id":"942d2c4a-6ecd-545a-a687-b8420b25b9e3","safe_urls":[{"url":"https://www.wired.com/gallery/best-travel-adapters/?utm_source=chatgpt.com"}],"entities":[{"entity_type":"search","ref":"turn525619search5"}]}]},{"p":"/message/metadata/safe_urls","o":"append","v":["https://www.wired.com/gallery/best-travel-adapters/?utm_source=chatgpt.com"]}]}       

